interface User {
  id: string | number;
  orgId: string | number;
  org?: unknown;
  [key: string]: unknown;
}

async function loadUser(id: string | number): Promise<User> {
  const res = await fetch(`/api/users/${id}`);
  if (!res.ok) {
    throw new Error(`bad status ${res.status}`);
  }
  const user = (await res.json()) as User;

  const orgRes = await fetch(`/api/orgs/${user.orgId}`);
  if (!orgRes.ok) {
    throw new Error(`bad status ${orgRes.status}`);
  }
  user.org = await orgRes.json();

  return user;
}

async function loadUsers(ids: Array<string | number>): Promise<User[]> {
  return Promise.all(ids.map((id) => loadUser(id)));
}

module.exports = { loadUser, loadUsers };

interface User {
  id: string;
  orgId: string;
  org?: Org;
}

interface Org {
  id: string;
  name?: string;
}

async function fetchJson<T>(url: string): Promise<T> {
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error(`Request failed with status ${res.status}: ${url}`);
  }
  return (await res.json()) as T;
}

async function loadUser(id: string): Promise<User> {
  const user = await fetchJson<User>(`/api/users/${encodeURIComponent(id)}`);
  const org = await fetchJson<Org>(`/api/orgs/${encodeURIComponent(user.orgId)}`);
  return { ...user, org };
}

async function loadUsers(ids: string[]): Promise<User[]> {
  return Promise.all(ids.map((id) => loadUser(id)));
}

export { loadUser, loadUsers };
export default { loadUser, loadUsers };

- `Rc<RefCell<T>>`: single-threaded shared ownership + interior mutability. Cheap, but not `Send`/`Sync`; borrow rules enforced at runtime (`RefCell` can panic on conflicting borrows). Use for GUI/UI/local shared state.
- `Arc<Mutex<T>>`: thread-safe shared ownership + mutual exclusion. Atomic refcount; mutation requires locking (`Mutex` can block and may poison on panic). Use across threads.

```rust
use std::rc::Rc;
use std::cell::RefCell;

let shared = Rc::new(RefCell::new(5));
let a = Rc::clone(&shared);
*a.borrow_mut() += 1; // single-threaded
```

```rust
use std::sync::{Arc, Mutex};
use std::thread;

let shared = Arc::new(Mutex::new(5));
let s = Arc::clone(&shared);
thread::spawn(move || {
    *s.lock().unwrap() += 1; // multi-threaded
});
```

Rule of thumb: single-threaded → `Rc<RefCell<T>>`; shared across threads → `Arc<Mutex<T>>`.

- `Rc<RefCell<T>>`: single-threaded shared ownership + runtime-checked mutable borrows. Not `Send`/`Sync`. Use when data is shared within one thread and you need interior mutability.
- `Arc<Mutex<T>>`: thread-safe shared ownership + mutual exclusion. Use when multiple threads share mutable state. Locking can block and may deadlock if misused.

```rust
use std::rc::Rc;
use std::cell::RefCell;

let shared = Rc::new(RefCell::new(5));
let a = Rc::clone(&shared);
*a.borrow_mut() += 1; // runtime borrow check
```

```rust
use std::sync::{Arc, Mutex};

let shared = Arc::new(Mutex::new(5));
let a = Arc::clone(&shared);
*a.lock().unwrap() += 1; // blocking lock
```

Rule of thumb: single-threaded → `Rc<RefCell<T>>`; multi-threaded → `Arc<Mutex<T>>`.
